-- 同名マスタが重複している既存DBは、推測で関連付けず移行を停止する。
CREATE TEMPORARY TABLE overload_seed_guard (ok INT NOT NULL CHECK (ok = 1));
SELECT 0 FROM (
    SELECT name FROM exercises GROUP BY name HAVING COUNT(*) > 1
    UNION ALL
    SELECT name FROM muscle GROUP BY name HAVING COUNT(*) > 1
) duplicates LIMIT 1;
DROP TEMPORARY TABLE overload_seed_guard;
-- 名前で既存マスタを照合し、生成済みIDを前提にしない初期投入。
